<?php
require_once __DIR__.'/../includes/bootstrap.php';require_once __DIR__.'/../includes/Connectors.php';if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);header('Allow: POST');exit('Metode tidak diizinkan.');}verify_csrf();$user=require_login();$workspace=require_permission('connect');$type=(string)($_POST['source_type']??'');if($workspace['plan']==='free'){$error='Koneksi remote tersedia setelah akses Business disetujui admin.';}elseif($type==='api'&&!plan_limits($workspace)['api']){$error='Koneksi API hanya tersedia untuk Business.';}else{try{$id=DatanixConnectors::connectAndImport((int)$workspace['id'],(int)$user['id'],$_POST);audit_log('source.connected','data_source',$id,['type'=>$type]);flash('success','Koneksi diuji dan snapshot data berhasil diimpor.');redirect('datasets/sources.php');}catch(Throwable $e){error_log('Datanix source connect failed: '.substr($e->getMessage(),0,350));$error=$e->getMessage();}}
$st=$GLOBALS['pdo']->prepare('SELECT s.*,u.name owner_name,(SELECT d.id FROM datasets d WHERE d.source_id=s.id ORDER BY d.id LIMIT 1) dataset_id FROM data_sources s JOIN users u ON u.id=s.owner_id WHERE s.workspace_id=? ORDER BY s.created_at DESC');$st->execute([$workspace['id']]);$sources=$st->fetchAll();require_once __DIR__.'/../includes/header.php';$layout='app';datanix_header('Data sources','sources',$layout);
?>
<div class="page-head"><div><div class="section-kicker">CONNECTIONS</div><h1>Data sources</h1><p>Test koneksi dan konektor sebelum kembali ke daftar sumber.</p></div><a href="<?=e(url('datasets/sources.php'))?>" class="btn btn-light-outline">Kembali</a></div><?php if($error):?><div class="alert alert-danger"><strong>Koneksi belum berhasil.</strong> <?=e($error)?></div><?php endif;?><section class="panel"><div class="panel-head"><h2 class="panel-title">Sumber saat ini</h2></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Source</th><th>Type</th><th>Rows</th><th>Status</th></tr></thead><tbody><?php foreach($sources as $s):?><tr><td><?=e($s['name'])?></td><td><?=e(strtoupper($s['source_type']))?></td><td><?=e(format_number((int)$s['row_count']))?></td><td><?=e($s['status'])?></td></tr><?php endforeach;?></tbody></table></div></section>
